#include <iostream>
using namespace std;

int main() {
    int na;
    cout << "Masukkan nilai: ";
    cin >> na;                    // slide lupa membaca na
    switch (na) {
        case 100:
            cout << "Bagus";
            break;
        case 70:
            cout << "Lumayan";
            break;
        default:
            cout << "Nilai yang anda masukkan salah";
    }
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    double a, b;
    int menu;
    cout << "1. Tambah\n2. Kurang\n3. Kali\n4. Bagi\nPilih: ";
    cin >> menu;
    cout << "Dua bilangan: ";
    cin >> a >> b;

    switch (menu) {
        case 1: cout << a + b; break;
        case 2: cout << a - b; break;
        case 3: cout << a * b; break;
        case 4:
            if (b != 0) cout << a / b;      // if di dalam case
            else        cout << "Tidak bisa dibagi 0";
            break;
        default:
            cout << "Menu tidak tersedia";
    }
    return 0;
}

